const crypto = require('crypto');
const tokenKey = () => {
  const k = String($env.IG_TOKEN_KEY || '');
  if (k.length < 32) throw new Error('IG_TOKEN_KEY is missing on the server');
  return crypto.createHash('sha256').update(k, 'utf8').digest();
};
const encryptToken = (plain) => {
  const iv = crypto.randomBytes(12);
  const c = crypto.createCipheriv('aes-256-gcm', tokenKey(), iv);
  const ct = Buffer.concat([c.update(String(plain), 'utf8'), c.final()]);
  return Buffer.concat([Buffer.from([1]), iv, c.getAuthTag(), ct]).toString('base64');
};
const decryptToken = (b64) => {
  const b = Buffer.from(String(b64 || ''), 'base64');
  if (b.length < 30 || b[0] !== 1) throw new Error('no usable Instagram token stored for this account');
  const d = crypto.createDecipheriv('aes-256-gcm', tokenKey(), b.subarray(1, 13));
  d.setAuthTag(b.subarray(13, 29));
  return Buffer.concat([d.update(b.subarray(29)), d.final()]).toString('utf8');
};

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const scrub = (s) => String(s || '').replace(/[A-Za-z0-9_\-]{40,}/g, '[redacted]').slice(0, 300);
async function graphCall(ctx, { what, method = 'GET', url, token, qs, form, json, tries = 1 }) {
  const headers = {};
  if (token) headers.Authorization = `Bearer ${token}`;
  let body;
  if (form) { headers['Content-Type'] = 'application/x-www-form-urlencoded'; body = new URLSearchParams(form).toString(); }
  else if (json) { headers['Content-Type'] = 'application/json'; body = JSON.stringify(json); }
  for (let attempt = 1; ; attempt++) {
    let r;
    try {
      r = await ctx.helpers.httpRequest({ method, url, qs, headers, body, json: false,
        returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 20000 });
    } catch (e) {
      if (attempt < tries) { await sleep(700 * attempt); continue; }
      const err = new Error(`${what}: could not reach Instagram (${scrub(e.code || e.message)})`);
      err.kind = 'network'; throw err;
    }
    let data = r.body;
    if (Buffer.isBuffer(data)) data = data.toString('utf8');
    if (typeof data === 'string') { try { data = JSON.parse(data); } catch (e) { data = { raw: scrub(data) }; } }
    if (r.statusCode >= 500 && attempt < tries) { await sleep(700 * attempt); continue; }
    if (r.statusCode >= 400) {
      const m = (data && (data.error || data)) || {};
      const err = new Error(`${what}: HTTP ${r.statusCode}: ${scrub(m.message || m.error_message || m.raw || 'error')}` +
                            (m.code ? ` (code ${m.code}${m.error_subcode ? '/' + m.error_subcode : ''})` : ''));
      err.kind = 'http'; err.status = r.statusCode; err.metaCode = m.code; throw err;
    }
    return data;
  }
}

// One output item per account. The new token is encrypted here and never output.
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  if (!j.id) continue;                         // a zero-row SELECT still emits {success:true}
  const base = { id: j.id, account_ref: j.account_ref, ig_username: j.ig_username, studio_name: j.studio_name,
                 old_expires_at: j.token_expires_at };
  if (!j.refresh_due) { out.push({ json: { ...base, status: 'not_due', token_enc: '', expires_in: 0, error: '' } }); continue; }
  try {
    const r = await graphCall(this, { what: 'token refresh', url: 'https://graph.instagram.com/refresh_access_token',
      qs: { grant_type: 'ig_refresh_token', access_token: decryptToken(j.token_enc) }, tries: 2 });
    if (!r.access_token) throw new Error('token refresh: no token in the response');
    out.push({ json: { ...base, status: 'refreshed', token_enc: encryptToken(r.access_token),
                       expires_in: Number(r.expires_in) || 5184000, error: '' } });
  } catch (e) {
    out.push({ json: { ...base, status: 'failed', token_enc: '', expires_in: 0, error: String(e.message).slice(0, 400) } });
  }
}
return out;

// One email, only if something needs a human.
const rows = $input.all().map((i) => i.json).filter((r) => r.id);
const soon = (r) => r.token_expires_at && (new Date(r.token_expires_at) - Date.now()) < 10 * 86400e3;
const bad = rows.filter((r) => r.status === 'failed' || soon(r));
if (!bad.length) return [];
const who = (r) => `${r.ig_username ? '@' + r.ig_username : r.account_ref} (${r.studio_name})`;
return [{ json: {
  to: 'founders',
  subject: `Instagram token problem: ${bad.map(who).join(', ')}`,
  heading: 'An Instagram token needs attention. If it expires, that studio\u2019s leads get no replies.',
  lines: [
    ...bad.map((r) => `${who(r)}: ` + (r.status === 'failed' ? `refresh FAILED (${r.token_error}). ` : '') +
                     (r.token_expires_at ? `Expires ${String(r.token_expires_at).slice(0, 10)}.` : 'Expiry unknown.')),
    'The job retries every day. If it keeps failing, send the studio a new connect link: python3 workflows/build/ig_connect_link.py <studio id>.',
  ],
} }];
